function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const special = [1900, 2000, 1904, 1996, 2016, 2019, 1999, 1901];
  const year = rand() < 0.3 ? special[int(0, special.length - 1)] : int(1900, 2019);
  const month = rand() < 0.2 ? (rand() < 0.5 ? 2 : 12) : int(1, 12);
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const lengths = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const last = lengths[month - 1];
  const roll = rand();
  const day = roll < 0.2 ? last : roll < 0.3 ? 1 : int(1, last);
  const pad = (value) => String(value).padStart(2, '0');
  return [`${year}-${pad(month)}-${pad(day)}`];
}
